<script>
    const MODULES=[
      {title:"Course 1 - Olfaction Training (8 modules, Creezy Courtoy)",items:["Introduction to Olfaction and to Odors","The Psychology and Physiology of the Olfactory Sense","The Olfactory Sense Training; the beneficial power of flowers and plants","Research on Olfaction; Becoming a Certified Olfaction Trainer","One module = one week; personal Zoom meeting before and survey after"]},
      {title:"Course 2 - Natural Aromatherapy (8 modules, Hana Tisserand)",items:["History and cultural context of aromatherapy and aromatic medicine","Essential oils: production, quality control and safety","Effects of essential oils on our body; aromatherapy in practice","Essential oil profiles (Lavender, Peppermint, Tea Tree, Eucalyptus, Rose, Jasmine, Bergamot...)","Using essential oils and creating a functional fragrance"]},
      {title:"Course 3 - Natural Perfumery (10 modules, Andrej Babicky)",items:["Introduction to Natural Perfumery and the New Luxury Code","Olfactory families; natural raw materials & extraction techniques","Study of the 50 most common natural raw materials","Perfume structure and creation; accord exercises","Modules 6 to 8: creative exploration of simple and complex accords","From idea to perfume; certification and future prospects; final one-on-one Zoom"]},
    ];
    let openIdx=0;
    function renderAcc(){
      document.getElementById('accordion').innerHTML=MODULES.map((m,i)=>`
        <div class="border-b" style="border-color:rgba(11,65,49,.15);">
          <button onclick="openIdx=${openIdx===i?-1:i};renderAcc();" class="w-full flex items-center justify-between gap-4 text-white px-5 sm:px-6 py-5 text-left" style="background:var(--green-primary);">
            <span class="font-serif text-lg sm:text-xl lg:text-2xl">${m.title}</span>
            <svg class="shrink-0" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="transition:transform .3s;transform:rotate(${openIdx===i?180:0}deg)"><path d="M6 9l6 6 6-6"/></svg>
          </button>
          ${openIdx===i?`<div class="bg-white px-5 sm:px-6 lg:px-10 py-7"><ul class="space-y-3 text-[17px] sm:text-[18px] leading-relaxed" style="color:var(--text-dark);">${m.items.map(it=>`<li class="flex gap-3"><span style="color:var(--soft-sage);">&#9670;</span><span>${it}</span></li>`).join('')}</ul></div>`:''}
        </div>`).join('');
    }
    renderAcc();
    
  </script>

